created() {
  this.setValue('students', this.initialStudents.map(item => ({
    id: item.id,
    name: item.name,
    grades: Object.assign({}, item.grades)
  })));
  const weights = {};
  this.assignments.forEach(item => {
    weights[item.id] = item.weight;
  });
  this.setValue('weights', weights);
}

updateGrade(studentId, assignmentId, event) {
  const value = Math.max(0, Math.min(100, Number(event.target.value) || 0));
  this.setValue('students', this.students.map(student => student.id === studentId ? Object.assign({}, student, {
    grades: Object.assign({}, student.grades, {
      [assignmentId]: value
    })
  }) : student));
  this.setValue('changeCount', this.changeCount + 1);
  this.setValue('lastEdited', studentId + ':' + assignmentId);
  this.emitEvent('grade-change', {
    studentId,
    assignmentId,
    value
  });
}

updateWeight(id, event) {
  this.setValue('weights', Object.assign({}, this.weights, {
    [id]: Number(event.target.value) || 0
  }));
  this.setValue('changeCount', this.changeCount + 1);
}

resetWeights() {
  const next = {};
  this.assignments.forEach(item => {
    next[item.id] = item.weight;
  });
  this.setValue('weights', next);
  this.setValue('changeCount', this.changeCount + 1);
}

publish() {
  this.setValue('published', true);
  this.emitEvent('publish', this.rows.map(row => ({
    id: row.id,
    total: row.total
  })));
}

inited() {
  const initialStudents = this.data.get("initialStudents");
  const students = initialStudents.map(item => ({
    id: item.id,
    name: item.name,
    grades: Object.assign({}, item.grades)
  }));
  this.data.set("students", students);
  const weights = {};
  const assignments = this.data.get("assignments");
  assignments.forEach(item => {
    weights[item.id] = item.weight;
  });
  this.data.set("weights", weights);
  this.watch("changeCount", () => {
    this.data.set("published", false);
  });
}

updateGrade(studentId, assignmentId, event) {
  const value = Math.max(0, Math.min(100, Number(event.target.value) || 0));
  const students = this.data.get("students");
  const nextStudents = students.map(student => student.id === studentId ? Object.assign({}, student, {
    grades: Object.assign({}, student.grades, {
      [assignmentId]: value
    })
  }) : student);
  this.data.set("students", nextStudents);
  const changeCount = this.data.get("changeCount");
  this.data.set("changeCount", changeCount + 1);
  this.data.set("lastEdited", studentId + ":" + assignmentId);
  this.emitEvent("grade-change", {
    studentId,
    assignmentId,
    value
  });
}

updateWeight(id, event) {
  const weights = this.data.get("weights");
  const nextWeights = Object.assign({}, weights, {
    [id]: Number(event.target.value) || 0
  });
  this.data.set("weights", nextWeights);
  const changeCount = this.data.get("changeCount");
  this.data.set("changeCount", changeCount + 1);
}

resetWeights() {
  const assignments = this.data.get("assignments");
  const next = {};
  assignments.forEach(item => {
    next[item.id] = item.weight;
  });
  this.data.set("weights", next);
  const changeCount = this.data.get("changeCount");
  this.data.set("changeCount", changeCount + 1);
}

publish() {
  this.data.set("published", true);
  const rows = this.data.get("rows");
  this.emitEvent("publish", rows.map(row => ({
    id: row.id,
    total: row.total
  })));
}

locked() {
  if (this.locked) this.setValue('crop', Object.assign({}, this.crop, {
    height: Math.round(this.crop.width * this.canvas.width / this.canvas.height)
  }));
}

update(field, event) {
  let value = Math.max(0, Math.min(100, Number(event.target.value) || 0));
  const crop = Object.assign({}, this.crop, {
    [field]: value
  });
  if (this.locked && field === 'width') crop.height = Math.min(100, Math.round(value * this.canvas.width / this.canvas.height));
  this.setValue('crop', crop);
  this.emitEvent('change', crop);
}

inited() {
  this.data.set('crop', Object.assign({}, this.data.get('initialCrop')));
  this.watch('locked', () => {
    if (this.data.get('locked')) {
      const crop = this.data.get('crop');
      const canvas = this.data.get('canvas');
      const newHeight = Math.round(crop.width * canvas.width / canvas.height);
      this.data.set('crop', Object.assign({}, crop, {
        height: Math.min(100, newHeight)
      }));
    }
  });
}

update(field, event) {
  let value = Math.max(0, Math.min(100, Number(event.target.value) || 0));
  const crop = Object.assign({}, this.data.get('crop'), {
    [field]: value
  });
  if (this.data.get('locked') && field === 'width') {
    const canvas = this.data.get('canvas');
    crop.height = Math.min(100, Math.round(value * canvas.width / canvas.height));
  }
  this.setValue('crop', crop);
  this.emitEvent('change', crop);
}

claim() {
  this.setValue('owner', this.owner ? '' : '当前值班员');
  this.addTimeline(this.owner ? '事件已认领' : '已取消认领');
}

advance() {
  const index = this.stageIndex;
  if (index >= this.stages.length - 1) return;
  const next = this.stages[index + 1];
  this.setValue('status', next);
  this.addTimeline('推进至' + this.statusText(next));
  this.emitEvent('status-change', next);
}

toggleCheck(id) {
  this.setValue('checklist', this.checklist.map(item => item.id === id ? Object.assign({}, item, {
    done: !item.done
  }) : item));
}

addNote(event) {
  event.preventDefault();
  const text = this.note.trim();
  if (!text) return;
  this.addTimeline(text);
  this.setValue('note', '');
}

escalate() {
  const next = this.severity === 'P2' ? 'P1' : 'P0';
  this.setValue('severity', next);
  this.addTimeline('严重度升级为 ' + next);
  this.emitEvent('escalate', next);
}

resolve() {
  if (!this.canResolve) return;
  this.setValue('status', 'resolved');
  this.addTimeline('事件已关闭');
  this.emitEvent('resolve', {
    id: this.incidentId,
    elapsed: this.elapsed
  });
}

addTimeline(text) {
  const now = new Date().toLocaleTimeString('zh-CN', {
    hour: '2-digit',
    minute: '2-digit'
  });
  this.setValue('timeline', [{
    id: Date.now(),
    time: now,
    text
  }].concat(this.timeline));
}

claim() {
  this.data.set('owner', this.data.get('owner') ? '' : '当前值班员');
  this.addTimeline(this.data.get('owner') ? '事件已认领' : '已取消认领');
}

advance() {
  const index = this.data.get('stageIndex');
