toggleCheck(id) {
  this.data.set('checklist', this.data.get('checklist').map(item => item.id === id ? Object.assign({}, item, {
    done: !item.done
  }) : item));
}

addNote(event) {
  event.preventDefault();
  const text = this.data.get('note').trim();
  if (!text) return;
  this.addTimeline(text);
  this.data.set('note', '');
}

escalate() {
  const next = this.data.get('severity') === 'P2' ? 'P1' : 'P0';
  this.data.set('severity', next);
  this.addTimeline('严重度升级为 ' + next);
  this.emitEvent('escalate', next);
