    minute: '2-digit'
  });
  this.data.set('timeline', [{
    id: Date.now(),
    time: now,
    text
  }].concat(this.data.get('timeline')));
}

refreshClock() {
  this.setValue('lastSynced', new Date().toLocaleTimeString('zh-CN', {
    hour12: false
  }));
}

toggleBatch(id) {
  const list = this.selectedIds;
  this.setValue('selectedIds', list.indexOf(id) >= 0 ? list.filter(item => item !== id) : list.concat(id));
}

applyAdjustment() {
  if (!this.canApply) return;
  const ids = this.selectedIds;
  const before = this.batches.map(item => Object.assign({}, item));
  const next = this.batches.map(item => ids.indexOf(item.id) >= 0 ? Object.assign({}, item, {
    quantity: Math.max(0, Math.min(item.capacity, item.quantity + this.adjustment))
  }) : item);
  this.setValue('batches', next);
  this.setValue('history', [{
    id: Date.now(),
    reason: this.reason,
    count: ids.length,
    delta: this.adjustment,
    before
  }].concat(this.history).slice(0, 5));
  this.setValue('selectedIds', []);
  this.setValue('adjustment', 0);
  this.emitEvent('inventory-change', next);
}

undo() {
  const history = this.history;
  if (!history.length) return;
  this.setValue('batches', history[0].before.map(item => Object.assign({}, item)));
  this.setValue('history', history.slice(1));
  this.emitEvent('inventory-change', this.batches);
}

refreshClock() {
  this.data.set("lastSynced", new Date().toLocaleTimeString("zh-CN", {
    hour12: false
  }));
}

toggleBatch(id) {
  const list = this.data.get("selectedIds");
  this.data.set("selectedIds", list.indexOf(id) >= 0 ? list.filter(item => item !== id) : list.concat(id));
}

applyAdjustment() {
  if (!this.data.get("canApply")) return;
  const ids = this.data.get("selectedIds");
  const before = this.data.get("batches").map(item => Object.assign({}, item));
  const next = this.data.get("batches").map(item => ids.indexOf(item.id) >= 0 ? Object.assign({}, item, {
    quantity: Math.max(0, Math.min(item.capacity, item.quantity + this.data.get("adjustment")))
  }) : item);
  this.data.set("batches", next);
  this.data.set("history", [{
    "id": Date.now(),
    "reason": this.data.get("reason"),
    "count": ids.length,
    "delta": this.data.get("adjustment"),
    "before": before
  }].concat(this.data.get("history")).slice(0, 5));
  this.data.set("selectedIds", []);
  this.data.set("adjustment", 0);
  this.emitEvent("inventory-change", next);
}

undo() {
  const history = this.data.get("history");
  if (!history.length) return;
  this.data.set("batches", history[0].before.map(item => Object.assign({}, item)));
  this.data.set("history", history.slice(1));
  this.emitEvent("inventory-change", this.data.get("batches"));
}

estimate(event) {
  event.preventDefault();
  if (this.weight <= 0) {
    this.setValue('error', '重量必须大于 0');
    this.setValue('result', null);
    return;
  }
  const region = this.selectedRegion;
  const fee = (region.base + Math.max(0, Math.ceil(this.weight - 1)) * 5) * (this.express ? 1.5 : 1);
  const result = {
    fee: fee.toFixed(2),
    days: this.express ? 1 : region.code === 'remote' ? 5 : 3
  };
  this.setValue('error', '');
  this.setValue('result', result);
  this.emitEvent('estimate', result);
}

reset() {
  this.setValue('weight', 1);
  this.setValue('express', false);
  this.setValue('result', null);
  this.setValue('error', '');
}

inited() {
  this.watch('regions', regions => {
    if (regions && regions.length > 0) {
      const current = this.data.get('regionCode');
      const found = regions.find(item => item.code === current);
      if (!found) {
        this.data.set('regionCode', regions[0].code);
      }
    }
  });
  this.watch('weight', weight => {
    if (weight <= 0) {
      this.data.set('error', '重量必须大于 0');
      this.data.set('result', null);
    } else {
      this.data.set('error', '');
    }
  });
  this.watch('regionCode', regionCode => {
    const regions = this.data.get('regions');
    if (regions && regions.length > 0) {
      const found = regions.find(item => item.code === regionCode);
      if (!found) {
        this.data.set('regionCode', regions[0].code);
      }
    }
  });
}

estimate(event) {
  event.preventDefault();
  const weight = this.data.get('weight');
  if (weight <= 0) {
    this.setValue('error', '重量必须大于 0');
    this.setValue('result', null);
    return;
  }
  const selectedRegion = this.data.get('selectedRegion');
  const express = this.data.get('express');
  const fee = (selectedRegion.base + Math.max(0, Math.ceil(weight - 1)) * 5) * (express ? 1.5 : 1);
  const result = {
    fee: fee.toFixed(2),
    days: express ? 1 : selectedRegion.code === 'remote' ? 5 : 3
  };
  this.setValue('error', '');
  this.setValue('result', result);
  this.emitEvent('estimate', result);
}

reset() {
  this.setValue('weight', 1);
  this.setValue('express', false);
  this.setValue('result', null);
  this.setValue('error', '');
}

created() {
  this.setValue('tickets', this.initialTickets.map(ticket => Object.assign({}, ticket, {
    tags: ticket.tags.slice(),
    messages: ticket.messages.map(message => Object.assign({}, message))
  })));
  this.setValue('selectedId', this.initialTickets[0] ? this.initialTickets[0].id : null);
}

selectTicket(id) {
  this.setValue('selectedId', id);
  this.setValue('replyDraft', '');
  this.setValue('mergeTargetId', null);
}

sendReply(event) {
  event.preventDefault();
  const text = this.replyDraft.trim();
  const id = this.selectedId;
  if (!text || id === null) return;
  const message = {
    id: Date.now(),
    author: this.internalNote ? '内部备注' : '客服',
    text,
    internal: this.internalNote
  };
  this.setValue('tickets', this.tickets.map(ticket => ticket.id === id ? Object.assign({}, ticket, {
    messages: ticket.messages.concat(message),
    status: this.internalNote ? ticket.status : 'pending'
  }) : ticket));
  this.setValue('replyDraft', '');
  this.emitEvent('reply', {
    ticketId: id,
    message
  });
}

changeStatus(status) {
  const id = this.selectedId;
  this.setValue('tickets', this.tickets.map(ticket => ticket.id === id ? Object.assign({}, ticket, {
    status
  }) : ticket));
  this.emitEvent('status', {
    ticketId: id,
    status
  });
}

assignAgent(event) {
  const assignee = event.target.value;
  const id = this.selectedId;
  this.setValue('tickets', this.tickets.map(ticket => ticket.id === id ? Object.assign({}, ticket, {
    assignee
  }) : ticket));
  this.emitEvent('assign', {
    ticketId: id,
    assignee
  });
}

mergeTicket() {
  const sourceId = this.selectedId;
  const targetId = this.mergeTargetId;
  if (!targetId) return;
  const source = this.tickets.find(ticket => ticket.id === sourceId);
  this.setValue('tickets', this.tickets.map(ticket => ticket.id === targetId ? Object.assign({}, ticket, {
    messages: ticket.messages.concat(source.messages)
  }) : ticket).filter(ticket => ticket.id !== sourceId));
  this.setValue('selectedId', targetId);
  this.emitEvent('merge', {
    sourceId,
    targetId
  });
}

inited() {
  this.setValue('tickets', this.data.get("initialTickets").map(ticket => Object.assign({}, ticket, {
    tags: ticket.tags.slice(),
    messages: ticket.messages.map(message => Object.assign({}, message))
  })));
  this.setValue('selectedId', this.data.get("initialTickets")[0] ? this.data.get("initialTickets")[0].id : null);
}

attached() {
  this.__migrationSyncSelectValues();
  this._timer = setInterval(() => {
    this.data.set('nowTick', this.data.get('nowTick') + 1);
  }, 60000);
}

selectTicket(id) {
  this.data.set('selectedId', id);
  this.data.set('replyDraft', '');
  this.data.set('mergeTargetId', null);
}

sendReply(event) {
  event.preventDefault();
  const text = this.data.get('replyDraft').trim();
  const id = this.data.get('selectedId');
  if (!text || id === null) return;
  const message = {
    id: Date.now(),
    author: this.data.get('internalNote') ? '内部备注' : '客服',
    text,
    internal: this.data.get('internalNote')
  };
  this.data.set('tickets', this.data.get('tickets').map(ticket => ticket.id === id ? Object.assign({}, ticket, {
    messages: ticket.messages.concat(message),
    status: this.data.get('internalNote') ? ticket.status : 'pending'
  }) : ticket));
  this.data.set('replyDraft', '');
  this.fire('reply', {
    ticketId: id,
    message
  });
}

changeStatus(status) {
  const id = this.data.get('selectedId');
  this.data.set('tickets', this.data.get('tickets').map(ticket => ticket.id === id ? Object.assign({}, ticket, {
    status
  }) : ticket));
  this.fire('status', {
    ticketId: id,
    status
  });
}

assignAgent(event) {
  const assignee = event.target.value;
  const id = this.data.get('selectedId');
  this.data.set('tickets', this.data.get('tickets').map(ticket => ticket.id === id ? Object.assign({}, ticket, {
    assignee
  }) : ticket));
  this.fire('assign', {
    ticketId: id,
    assignee
  });
}

mergeTicket() {
  const sourceId = this.data.get('selectedId');
  const targetId = this.data.get('mergeTargetId');
  if (!targetId) return;
  const source = this.data.get('tickets').find(ticket => ticket.id === sourceId);
  this.data.set('tickets', this.data.get('tickets').map(ticket => ticket.id === targetId ? Object.assign({}, ticket, {
    messages: ticket.messages.concat(source.messages)
  }) : ticket).filter(ticket => ticket.id !== sourceId));
  this.data.set('selectedId', targetId);
  this.fire('merge', {
    sourceId,
    targetId
  });
}
